using System;
using System.Collections.Generic;
using System.Linq;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;
using Lib.Captcha.CaptchaComVn;
using Libs.Report;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace UnitTest
{
    [TestClass()]
    public class CaptchaComVnServiceTests
    {
        [TestMethod()]
        public void Getcaptcha()
        {

            string url = "http://naptien.vinaphone.com.vn/Home/GenerateCaptcha";
            var capImageBase64 = Task.Run(async () => await GetImageBase64(url)).Result;
            //var capImageBase64 = "";
            CaptchaComVnService captchaComVn = new CaptchaComVnService();

            var result = captchaComVn.ImageToText(capImageBase64, 3);

            Console.WriteLine(result);

        }

        public static async Task<string> GetImageBase64(string url)
        {
            var uri = new Uri(url);
            var httpClient = new HttpClient();
            httpClient.Timeout = TimeSpan.FromSeconds(60);
            httpClient.DefaultRequestHeaders.Add("User-Agent", "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/71.0.3578.98 Safari/537.36");
            try
            {
                var response = await httpClient.GetAsync(uri);
                var responseContent = await response.Content.ReadAsStringAsync();
                httpClient.Dispose();
                return responseContent;
            }
            catch (Exception e)
            {
                return String.Empty;
            }
        }
    }
}
